interface User {
  name: string
  email: string
}

// Fetch user data from /api/users/profile
async function getUser() {
  try {
    const res = await fetch('/api/users/profile')
    return res.json()
  } catch {
    // Return mock data for build time
    return { name: 'Sample User', email: 'sample@example.com' }
  }
}

export default async function UserProfile() {
  const user = await getUser()

  return (
    <div>
      <h2>User Profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  )
}
